import{_ as t,o as n,c as a,a3 as r}from"./chunks/framework.B5WAEDB7.js";const p=JSON.parse('{"title":"Roles","description":"The four roles in an ApptiveGrid Space and what they allow.","frontmatter":{"title":"Roles","description":"The four roles in an ApptiveGrid Space and what they allow."},"headers":[],"relativePath":"en/zusammenarbeit/rollen.md","filePath":"en/zusammenarbeit/rollen.md","lastUpdated":1788108473000}'),s={name:"en/zusammenarbeit/rollen.md"};function i(o,e,l,d,h,c){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Roles&quot;">​</a></h1><p>Every person in a Space has exactly one <strong>role</strong>. It determines what that person may do.</p><p>When inviting, ApptiveGrid asks: <em>The user can:</em> — and offers the roles to choose from.</p><h2 id="the-four-roles" tabindex="-1">The four roles <a class="header-anchor" href="#the-four-roles" aria-label="Permalink to &quot;The four roles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Description in the interface</th></tr></thead><tbody><tr><td><strong>Owner</strong></td><td>The person the Space belongs to</td></tr><tr><td><strong>Manage</strong></td><td><em>edit and configure this Space</em></td></tr><tr><td><strong>Edit entries</strong></td><td><em>edit content but not configure anything</em></td></tr><tr><td><strong>Read only</strong></td><td><em>not edit or configure the Space</em></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Why &quot;Manage&quot; and not &quot;Administrator&quot;</p><p>In the interface, this role is called <strong>Manage</strong>. In one place — <a href="/en/integrationen/api-zugangsdaten">API Credentials</a> — a comparable level uses the term <em>Admin</em> instead. It refers to a similar level of permission, but these are two separate things: roles apply to people within a Space, API credentials apply to programmatic access across all your Spaces.</p></div><h2 id="what-the-roles-allow" tabindex="-1">What the roles allow <a class="header-anchor" href="#what-the-roles-allow" aria-label="Permalink to &quot;What the roles allow&quot;">​</a></h2><p>The line runs between <strong>content</strong> and <strong>structure</strong>:</p><ul><li><strong>Content</strong> is the entries and how they&#39;re presented.</li><li><strong>Structure</strong> is anything that creates, deletes, or exposes something externally.</li></ul><table tabindex="0"><thead><tr><th></th><th style="text-align:center;">Read only</th><th style="text-align:center;">Edit entries</th><th style="text-align:center;">Manage</th></tr></thead><tbody><tr><td><strong>Read</strong> — Grids, entries, fields, views, Flows, users</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td>Create, change, delete entries</td><td style="text-align:center;">–</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td>Update a view</td><td style="text-align:center;">–</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td>Configure a Flow step</td><td style="text-align:center;">–</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td>Create, change, delete fields</td><td style="text-align:center;">–</td><td style="text-align:center;">–</td><td style="text-align:center;">✓</td></tr><tr><td>Create, change, delete Grids</td><td style="text-align:center;">–</td><td style="text-align:center;">–</td><td style="text-align:center;">✓</td></tr><tr><td>Create, delete, share views</td><td style="text-align:center;">–</td><td style="text-align:center;">–</td><td style="text-align:center;">✓</td></tr><tr><td>Create, change, delete forms</td><td style="text-align:center;">–</td><td style="text-align:center;">–</td><td style="text-align:center;">✓</td></tr><tr><td>List forms</td><td style="text-align:center;">–</td><td style="text-align:center;">–</td><td style="text-align:center;">✓</td></tr><tr><td>Create, delete Flows; add and remove steps</td><td style="text-align:center;">–</td><td style="text-align:center;">–</td><td style="text-align:center;">✓</td></tr><tr><td>Share Space, manage shares</td><td style="text-align:center;">–</td><td style="text-align:center;">–</td><td style="text-align:center;">✓</td></tr><tr><td>Create, change, delete Spaces</td><td style="text-align:center;">–</td><td style="text-align:center;">–</td><td style="text-align:center;">✓</td></tr><tr><td>Create, change, test webhooks</td><td style="text-align:center;">–</td><td style="text-align:center;">–</td><td style="text-align:center;">✓</td></tr><tr><td>Manage API credentials</td><td style="text-align:center;">–</td><td style="text-align:center;">–</td><td style="text-align:center;">✓</td></tr></tbody></table><p>The <strong>Owner</strong> role is equivalent to <em>Manage</em> and additionally may adjust the plan and seats. The interface says so explicitly: <em>The owner can adjust the plan.</em></p><h2 id="three-things-that-surprise-people" tabindex="-1">Three things that surprise people <a class="header-anchor" href="#three-things-that-surprise-people" aria-label="Permalink to &quot;Three things that surprise people&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Edit entries reaches further than &quot;just entries&quot;</p><p>The short description <em>edit content but not configure anything</em> is a bit too narrow. Whoever has <strong>Edit entries</strong> may additionally:</p><ul><li><strong>Update views</strong> — change an existing view. This affects everyone using that view, including <a href="/en/zusammenarbeit/zugriff-beschraenken">shared links</a>.</li><li><strong>Configure Flow steps</strong> — change the settings of an existing step. Only <em>Manage</em> may create or delete new steps.</li></ul><p>Creating, deleting, and sharing remain reserved for <em>Manage</em> in both cases.</p></div><div class="tip custom-block"><p class="custom-block-title">Not every view change is the same</p><p>Under the hood, two kinds of view change are distinguished: one that <em>Edit entries</em> allows, and one that requires <em>Manage</em>. Which control falls into which category is deliberately not listed here — the assignment can change along with the interface.</p><p>If you&#39;re relying on someone with <em>Edit entries</em> <strong>not</strong> being able to change a specific setting, verify it with a test account.</p></div><div class="danger custom-block"><p class="custom-block-title">What this means for Flows</p><p>A person with <strong>Edit entries</strong> can change the configuration of a Flow step — for example the recipient of an email, or the target address of an HTTP request.</p><p>The process looks the same on the outside, but the result isn&#39;t. If a Flow sends sensitive data or contains <a href="/en/integrationen/ueberblick">credentials for an outside system</a>, think carefully about who in the Space has <strong>Edit entries</strong>.</p></div><div class="tip custom-block"><p class="custom-block-title">Readers don&#39;t see the forms list</p><p><strong>List forms</strong> is reserved for <em>Manage</em>. Any role, however, may <strong>read</strong> an individual form.</p><p>In practice this means: someone with only <em>Read only</em> won&#39;t find any forms in the navigation area under a Grid — but can still open and fill in a form if they have the link. This isn&#39;t a bug, it&#39;s by design.</p></div><h2 id="when-a-button-is-missing" tabindex="-1">When a button is missing <a class="header-anchor" href="#when-a-button-is-missing" aria-label="Permalink to &quot;When a button is missing&quot;">​</a></h2><p>ApptiveGrid only shows features when the role allows them. There&#39;s <strong>no error message</strong> and no grayed-out button — the feature is simply not there.</p><p>This is the most common reason for &quot;it looks different on my screen than on yours.&quot; In that case, check the role first.</p><p>→ <a href="/en/fehlerbehebung/fehlende-schaltflaechen">I can&#39;t see a button</a></p><h2 id="role-and-cost" tabindex="-1">Role and cost <a class="header-anchor" href="#role-and-cost" aria-label="Permalink to &quot;Role and cost&quot;">​</a></h2><p>Only <strong>Read only</strong> is free. <strong>Edit entries</strong>, <strong>Manage</strong>, and <strong>Owner</strong> each occupy a seat.</p><blockquote><p><em>The owner can purchase additional seats for users with editing rights. Read-only access is free.</em></p></blockquote><div class="tip custom-block"><p class="custom-block-title">When in doubt, start with &quot;Read only&quot;</p><p>Grant editing rights only where they&#39;re actually needed. Someone who&#39;s only meant to read data costs nothing — and can still fill in forms restricted to <em>Anyone in this Space</em>.</p></div><p>→ <a href="/en/zusammenarbeit/sitzplaetze">Seats</a></p><h2 id="changing-a-role" tabindex="-1">Changing a role <a class="header-anchor" href="#changing-a-role" aria-label="Permalink to &quot;Changing a role&quot;">​</a></h2><p>Open <strong>Share Space</strong> and change the role in the <em>Shared with</em> list. The change takes effect immediately.</p><p>Downgrading to <strong>Read only</strong> frees up a seat.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/zusammenarbeit/personen-einladen">Inviting people</a></li><li><a href="/en/zusammenarbeit/sitzplaetze">Seats</a></li><li><a href="/en/zusammenarbeit/zugriff-beschraenken">Access to shared content</a></li></ul>',30)])])}const m=t(s,[["render",i]]);export{p as __pageData,m as default};
